export const CORRECTIONS = {"poultry--avian-drugs--amr-5-rs-responsible-use":[{"severity":"contradicts","lectureSays":"โน้ตระบุว่า AMR 5 Rs คือ Right Drug, Right Dose, Right Duration, Right Time, Right Patient และอ้างที่มาว่าเป็นของ WHO ร่วมกับ OIE และ FAO Tripartite","evidenceSays":"กรอบ 5R ของ antimicrobial stewardship ทางสัตวแพทย์ที่ตีพิมพ์จริงคือ Responsibility, Review, Reduce, Replace, Refine โดยเน้น executive support, ทีมที่รับผิดชอบ, การ review สถานะเริ่มต้นและตั้งตัวชี้วัด แล้วจึง reduce, replace, refine การใช้ยา (Antimicrobial Stewardship in Veterinary Medicine, PMID 29916349, doi 10.1128/microbiolspec.ARBA-0023-2017) ค้นไม่พบว่า WHO, WOAH หรือ FAO เผยแพร่ mnemonic ชุด Right ภายใต้ชื่อ 5 Rs","examAdvice":"ข้อสอบถาม AMR 5 Rs ให้ตอบ Right Drug, Dose, Duration, Time, Patient ตามที่อาจารย์สอน แล้วจำไว้ว่ากรอบ 5R ในวารสารเป็นคนละชุด","sourceRef":"PMID 29916349"}],"poultry--avian-drugs--drug-withdrawal-period":[{"severity":"narrows","lectureSays":"โน้ตให้ withdrawal time ของ enrofloxacin ในไก่เนื้อเป็นค่าเดียวคือ 8 ถึง 10 วัน","evidenceSays":"งานศึกษาการสลายตัวของ enrofloxacin ในไก่ 5 สายพันธุ์ หลังป้อน 10 mg/kg นาน 5 วัน พบว่า WT ขึ้นกับสายพันธุ์ สายขนขาว AA broiler และ WOD168 ได้ประมาณ 2.30 ถึง 2.64 วัน ขณะที่สายขนเหลืองและไก่กระดูกดำได้ 8.16 ถึง 39.74 วัน โดย skin with fat เป็น limiting tissue ผิวหนังพร้อมไขมันวันที่ 14 สูงถึง 898.96 ไมโครกรัมต่อกิโลกรัม เกือบ 9 เท่าของ MRL (PMID 42056824, doi 10.1016/j.psj.2026.107002) ตัวเลขชุดนี้อ้างอิง MRL ของจีน","examAdvice":"ตอบ 8 ถึง 10 วันตามที่อาจารย์สอน แล้วเสริมได้ว่า WT จริงขึ้นกับสายพันธุ์และต้องยึดฉลากที่ขึ้นทะเบียน","sourceRef":"PMID 42056824"}],"poultry--avian-zoonosis--major-avian-zoonoses-viral":[{"severity":"narrows","lectureSays":"โน้ตระบุว่า NDV ในคนที่สัมผัสสัตว์ปีกเป็น conjunctivitis และ self-limiting โดยไม่มีข้อยกเว้น","evidenceSays":"mild conjunctivitis เป็นอาการหลักในคนจริง แต่มีรายงานเด็กอายุ 2 ปีที่ภูมิคุ้มกันบกพร่องติด pigeon variant ของ avian paramyxovirus type 1 หรือ APMV-1 แล้วเกิด neurologic infection จนเสียชีวิต (PMID 37987582, doi 10.3201/eid2912.230250) จึงบอกว่า self-limiting ทุกรายไม่ได้ ทั้งนี้แหล่งอ้างอิงเรียกเชื้อนี้ว่า APMV-1 ซึ่งเป็นชื่อกว้างกว่าที่โน้ตเรียกว่า Paramyxovirus type 1","examAdvice":"ตอบ conjunctivitis self-limiting ตามที่อาจารย์สอน แต่ถ้าโจทย์เป็นผู้ป่วยภูมิคุ้มกันบกพร่อง อย่าตอบว่าไม่มีอันตราย","sourceRef":"PMID 37987582"}],"poultry--biosecurity--production-metrics":[{"severity":"narrows","lectureSays":"โน้ตระบุว่า HD สูงกว่า HH เสมอ เพราะ HD ไม่สนใจ mortality","evidenceSays":"ที่ถูกคือ HD มากกว่าหรือเท่ากับ HH เท่ากันพอดีเมื่อ mortality เป็นศูนย์ และช่องว่างกว้างขึ้นตาม cumulative mortality ข้อมูลฝูง free-range ที่ mortality 8.1 ถึง 11.0 เปอร์เซ็นต์ ให้คู่ค่า HD/HH เป็น 56.4/55.4, 40.4/40.2 และช่วง peak 90.1/89.2 เปอร์เซ็นต์ (PMID 34069516, doi 10.3390/ani11051458)","examAdvice":"ตอบทิศทางว่า HD สูงกว่า HH ตามที่สอน แต่ถ้าโจทย์กำหนดให้ mortality เป็นศูนย์ ให้ตอบว่าเท่ากัน","sourceRef":"PMID 34069516"}],"poultry--first-week-mortality--pasgar-score-chick-quality-at-24h":[{"severity":"contradicts","lectureSays":"โน้ตระบุว่า Pasgar score มี 5 หมวด หมวดละ 0 ถึง 1 คะแนน รวมเต็ม 5 คะแนน สมบูรณ์เท่ากับ 5 และ Pasgar ตั้งแต่ 4 ขึ้นไปถือว่าลอตดี","evidenceSays":"สเกล 0 ถึง 5 เป็นไปไม่ได้ เพราะงานตีพิมพ์รายงานค่าเฉลี่ย Pasgar score 9.21 บวกลบ 0.89 ในกลุ่มไข่ฟักที่ฆ่าเชื้อด้วย clove essential oil (PMID 33142469, doi 10.1016/j.psj.2020.07.014) และงานร่วมชุด (PMID 21934018, doi 10.3382/ps.2011-01467) ระบุว่าคะแนนที่ต่ำลงมาจาก poor navel quality, red hocks และ red beaks เป็นหลัก ซึ่งไม่ตรงกับตัวอักษรที่โน้ตกาง นอกจากนี้โน้ตยังขัดกันเอง เพราะบอก 5 หมวด แต่ไล่ 6 ตัวอักษร P-A-S-G-A-R","examAdvice":"ข้อสอบถามคะแนน Pasgar ให้ตอบสเกล 0 ถึง 5 และเกณฑ์ 4 ตามที่อาจารย์สอน เพราะอาจารย์ตรวจเอง แล้วรู้ไว้ว่าสเกลจริงเต็มมากกว่า 5","sourceRef":"PMID 33142469"}],"poultry--first-week-mortality--vaccine-strategy-rolling-reaction-concept":[{"severity":"narrows","lectureSays":"โน้ตนิยาม rolling reaction ว่าคือการที่วัคซีนเชื้อเป็นก่อการติดเชื้อเฉพาะที่อย่างอ่อนแล้วไหลวนไปทั้งฝูงและกระตุ้นภูมิคุ้มกัน โดยวางไว้เหมือนเป็นศัพท์ที่มีนิยามทางการ","evidenceSays":"กลไกได้รับการพิสูจน์จริง ในการทดลอง CEO ILT vaccine ไก่ที่ไม่ได้ทำวัคซีนซึ่งนำเข้าไปสัมผัสในวันที่ 0, 4, 8, 12 และ 16 ตรวจพบเชื้อวัคซีนได้ และการให้วัคซีนทาง drinking water สัมพันธ์กับ non-uniform protection (PMID 22845327, doi 10.1080/03079457.2011.643222) แต่ตัวคำว่า rolling reaction ไม่ปรากฏเป็น defined term ใน PubMed","examAdvice":"ข้อสอบถาม rolling reaction ให้ตอบตามนิยามที่อาจารย์สอนได้เลย แต่อย่าอ้างว่าเป็นศัพท์มาตรฐานในวารสาร","sourceRef":"PMID 22845327"},{"severity":"narrows","lectureSays":"โน้ตระบุว่าช่วง MDA decay สัปดาห์ที่ 2 ถึง 3 คือ optimal vaccination window","evidenceSays":"งานหาเวลาที่เหมาะสมของวัคซีน IBD (Gumboro) แนะนำให้ทำวัคซีนวันที่ 21 แล้ว boost วันที่ 28 คือปลายสัปดาห์ 3 ต่อสัปดาห์ 4 และย้ำว่าต้องทำ 2 ครั้งจึงคุ้มครองทั้งฝูงได้ดี โดยวันที่เหมาะสมเป็นค่าเฉพาะฝูง ต้องคำนวณจาก MDA titre ที่วัดจริง ไม่ใช่กำหนดตามปฏิทิน (PMID 26018110, doi 10.4102/ojvr.v82i1.887)","examAdvice":"ตอบ week 2-3 ตามที่อาจารย์สอน แล้วเติมว่าในทางปฏิบัติต้องคำนวณวันจาก MDA titre ของฝูงจริง","sourceRef":"PMID 26018110"}],"poultry--nutrition--feed-processing-grinding-pelleting-crumbling":[{"severity":"contradicts","lectureSays":"โน้ตระบุว่าการอัดเม็ด pelleting ให้ better gizzard development","evidenceSays":"การทดลองในกรง 14 วัน เปรียบเทียบ mash กับ crumble ร่วมกับข้าวโพดบดหยาบ 0 ถึง 50 เปอร์เซ็นต์ พบว่าน้ำหนัก gizzard สัมพัทธ์ไม่เปลี่ยนตามข้าวโพดหยาบในสูตร crumble แต่เพิ่มขึ้นแบบเชิงเส้นในสูตร mash แปลว่าตัวกระตุ้น gizzard คืออนุภาคหยาบ ไม่ใช่การอัดเม็ด (PMID 25881586, doi 10.3382/ps/pev074) ส่วนข้อความเรื่อง reduce selective feeding และ FCR กับน้ำหนักตัวที่ดีขึ้นในรูป crumble หรือ pellet งานนี้สนับสนุน","examAdvice":"ถ้ามีตัวเลือกว่า pelleting ช่วย gizzard development ให้ตอบตามที่อาจารย์สอน แล้วจำไว้ว่าหลักฐานชี้ว่าอนุภาคหยาบต่างหากที่กระตุ้น gizzard","sourceRef":"PMID 25881586"}],"poultry--nutrition--protein-amino-acids":[{"severity":"narrows","lectureSays":"โน้ตให้ ideal AA profile เทียบ Lysine เท่ากับ 100 เป็นชุดค่าเดียวใช้ได้ทุกช่วงอายุ โดย Threonine เท่ากับ 67 ถึง 68.5","evidenceSays":"หลัก Lysine เท่ากับ 100 ถูกต้อง แต่ค่าตัวอื่นเป็นช่วงตามวิธีประเมิน งาน N balance ในไก่เนื้อ ROSS 308 ซึ่งเป็นสายพันธุ์เดียวกับตารางในโน้ต ได้ Arginine 105 ทั้งสองระยะ และ Tryptophan 17 ถึง 19 ตรงกับโน้ตดี แต่ได้ Threonine เพียง 60 ถึง 62 ต่ำกว่าโน้ต (PMID 26479521, doi 10.3390/ani3030558) ขณะที่ Poult Sci 2012 (PMID 22334755, doi 10.3382/ps.2011-01818) ได้ digestible Thr ต่อ Lys 66 ถึง 70 ซึ่งใกล้เคียงโน้ต","examAdvice":"ตอบตัวเลขตามตารางของอาจารย์ แล้วจำว่า Threonine ในวรรณกรรมมีช่วง 60 ถึง 70 แล้วแต่วิธีประเมิน","sourceRef":"PMID 26479521"}]};
